// Appel reactif (Mono) vers un service distant.
// On pose un timeout, puis des retries avec backoff et jitter.

Mono<Reponse> appel = clientHttp
    .appelerServicePaiement(commande)
    // 1) Timeout : on abandonne si pas de reponse en 2 secondes
    .timeout(Duration.ofSeconds(2))
    // 2) Retry : jusqu'a 3 tentatives, delai de base 100 ms
    //    qui double a chaque fois (backoff exponentiel)
    //    + jitter de 50 % pour etaler les tentatives
    .retryWhen(
        Retry.backoff(3, Duration.ofMillis(100))
             .jitter(0.5)
    );

// Remarque : on ne retente ainsi QUE des appels idempotents.
// Pour une operation sensible, on envoie une cle d'idempotence
// pour que le service ignore un eventuel doublon.

// On protege l'appel distant par un disjoncteur configure :
// - il s'ouvre si 50 % des appels echouent
// - il reste ouvert 10 secondes avant de tester a nouveau
// Si le disjoncteur est ouvert, on renvoie un fallback.

Mono<Prix> prix = clientHttp
    .appelerServiceTarifs(produit)
    .timeout(Duration.ofSeconds(2))
    // Le disjoncteur surveille les echecs de ce flux
    .transformDeferred(CircuitBreakerOperator.of(disjoncteurTarifs))
    // Repli : si l'appel echoue ou si le disjoncteur est ouvert,
    // on renvoie un prix par defaut au lieu de planter
    .onErrorResume(erreur -> Mono.just(Prix.parDefaut(produit)));

// Configuration type du disjoncteur :
//   failureRateThreshold = 50   (seuil d'ouverture en %)
//   waitDurationInOpenState = 10s (temps avant demi-ouvert)
